#!/bin/bash
# Generated by scripts/export-killercoda.ts. Passes (exit 0) when the named checks of lab-m10-probes pass.
# Environment overrides, for local tests: SHELF_BIN, KUBECONFIG, SHELF_MARKER_DIR, SHELF_COURSE_DIR, SHELF_LABS_DIR.
LAB=lab-m10-probes
CHECKS="cascade-liveness-local cascade-readiness-kept cascade-rolled-out cascade-no-restarts"
MARK="${SHELF_MARKER_DIR:-/tmp}"
SHELF="${SHELF_BIN:-/usr/local/bin/shelf}"
[ -f "$MARK/shelf-failed" ] && { echo "Setup failed: $(cat "$MARK/shelf-failed"). See /tmp/shelf-setup.log." >&2; exit 1; }
[ -f "$MARK/shelf-ready" ] || { echo "Setup is not finished. Wait for RESULT: ready in the first terminal, then click Check again." >&2; exit 1; }
export KUBECONFIG="${KUBECONFIG:-/root/.kube/config}"
cd "${SHELF_COURSE_DIR:-/root/course}" || { echo "The course folder is missing." >&2; exit 1; }
kubectl --context kind-reconcile --request-timeout=10s get nodes >/dev/null 2>&1 || { echo "The cluster is not reachable. Create it first (shelf up), and wait for the node to be Ready." >&2; exit 1; }
# Only this step's checks run, and each wait is capped at 30 s: the lab's own checks.yaml is replaced in a temporary copy of the labs folder.
LABS="${SHELF_LABS_DIR:-${SHELF_COURSE_DIR:-/root/course}/labs}"
T=$(mktemp -d) || { echo "Cannot make a temporary folder." >&2; exit 1; }
trap '[ -n "$T" ] && rm -rf "$T"' EXIT
for e in "$LABS"/*; do n=${e##*/}; [ "$n" = "$LAB" ] || ln -s "$e" "$T/$n"; done
cp -R "$LABS/$LAB" "$T/$LAB"
cat > "$T/$LAB/checks.yaml" <<'KILLERCODA_CHECKS'
apiVersion: labs.reconcile.example/v1
kind: LabChecks
lab: lab-m10-probes
checks:
  - id: cascade-liveness-local
    describe: The liveness probe of shelf-api-cascade asks /healthz, which does not check the database
    kubectl:
      - get
      - deployment
      - shelf-api-cascade
      - -n
      - shelf
      - -o
      - jsonpath={.spec.template.spec.containers[0].livenessProbe.httpGet.path}
    expect:
      equals: /healthz
    hint: In `shelf-probes/shelf-api-cascade.yaml` the liveness probe asks `/readyz`, which fails while the database is missing. Change its path to `/healthz` and apply the file.
  - id: cascade-readiness-kept
    describe: The readiness probe of shelf-api-cascade still asks /readyz, so the dependency check stays in readiness
    kubectl:
      - get
      - deployment
      - shelf-api-cascade
      - -n
      - shelf
      - -o
      - jsonpath={.spec.template.spec.containers[0].readinessProbe.httpGet.path}
    expect:
      equals: /readyz
    hint: Keep the readiness probe as it is. While the database is missing, the Pods should be not Ready and receive no traffic. Only the liveness probe changes.
  - id: cascade-rolled-out
    describe: All 3 replicas of shelf-api-cascade run the new Pod template
    kubectl:
      - get
      - deployment
      - shelf-api-cascade
      - -n
      - shelf
      - -o
      - jsonpath={.status.updatedReplicas}/{.status.replicas}
    expect:
      eventually:
        timeout: 30s
        interval: 3s
        expect:
          equals: 3/3
    hint: "Apply `shelf-probes/shelf-api-cascade.yaml` again. The new Pods will show `0/1` because the database is missing, and that is correct: the rollout does not finish, and this check reads only how many Pods use the new template."
  - id: cascade-no-restarts
    describe: No shelf-api-cascade container has been restarted since the fix
    kubectl:
      - get
      - pods
      - -n
      - shelf
      - -l
      - app.kubernetes.io/name=shelf-api-cascade
      - -o
      - jsonpath={.items[*].status.containerStatuses[0].restartCount}
    expect:
      matches: ^0( 0)*$
    hint: The old Pods had restarted many times. The Pods of the new template start at 0, and stay there if the liveness probe no longer depends on the database. Wait for the old Pods to go, then run the check again.
KILLERCODA_CHECKS
out=$(SHELF_LABS_DIR="$T" timeout 60 "$SHELF" verify "$LAB" 2>&1); rc=$?
if [ "$rc" -eq 124 ]; then echo "The checks took too long. Wait a few seconds and click Check again." >&2; exit 1; fi
if [ "$rc" -ge 2 ]; then echo "$out" >&2; exit 1; fi
bad=0
for id in $CHECKS; do
  printf '%s\n' "$out" | grep -Eq "^(PASS|SKIP) $id " && continue
  bad=1; printf '%s\n' "$out" | grep -E -A2 "^FAIL $id "
done
[ "$bad" -eq 0 ] || echo "If you just applied a change, it may still be rolling out: wait a few seconds and click Check again." >&2
exit "$bad"
